SET LOCAL aidash.scope = 'deployment';
UPDATE "authorization_bundles" SET "document" = (replace(replace(replace(replace(replace(replace(replace(replace(document::text, '"workspace.create"', '"thread.create"'), '"workspace.events"', '"thread.events"'), '"workspace.read"', '"thread.read"'), '"workspace.share"', '"thread.share"'), '"workspace.update"', '"thread.update"'), '"workspace_id"', '"thread_id"'), '"/workspace_id"', '"/thread_id"'), '"workspace"', '"thread"'))::jsonb, "revision" = "revision" + 1, "updated_at" = CURRENT_TIMESTAMP WHERE (document::text LIKE '%"workspace.create"%' OR document::text LIKE '%"workspace.events"%' OR document::text LIKE '%"workspace.read"%' OR document::text LIKE '%"workspace.share"%' OR document::text LIKE '%"workspace.update"%' OR document::text LIKE '%"workspace_id"%' OR document::text LIKE '%"/workspace_id"%' OR document::text LIKE '%"workspace"%');
